dtsPropsFor.Badge:
children: React.ReactNode;
  className?: string;
  /** Tonal colour. Default 'default'. */
  variant?: 'default' | 'success' | 'warning' | 'error' | 'info';
  /** Default 'sm'. */
  size?: 'sm' | 'md' | 'lg';

dtsPropsFor.Button:
children: React.ReactNode;
  /** Default 'primary' — solid black, the site's main action. */
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost';
  /** Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  fullWidth?: boolean;
  /** Merge styling onto a single child (e.g. an anchor) instead of rendering a <button>. */
  asChild?: boolean;
  className?: string;
  disabled?: boolean;
  type?: 'button' | 'submit' | 'reset';
  onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Card:
children: React.ReactNode;
  className?: string;
  /** 'elevated' is the house card: white, shadow-lg, grey border. Default 'default'. */
  variant?: 'default' | 'outlined' | 'elevated';
  /** Default 'md' (p-6). Use 'none' when the child supplies its own padding. */
  padding?: 'none' | 'sm' | 'md' | 'lg';
  /** Adds hover elevation and a pointer cursor. */
  hover?: boolean;
  asChild?: boolean;

dtsPropsFor.Section:
children: React.ReactNode;
  title?: string;
  subtitle?: string;
  /** Emoji used as the section icon — this library's icon convention. */
  icon?: string;
  className?: string;
  titleClassName?: string;
  contentClassName?: string;

dtsPropsFor.StatCard:
title: string;
  value: string | number;
  subtitle?: string;
  icon?: React.ReactNode;
  trend?: 'up' | 'down' | 'neutral';
  trendValue?: string;
  /** Colours the value. Default 'default' (near-black). */
  valueColor?: 'default' | 'success' | 'warning' | 'error';
  className?: string;

dtsPropsFor.SubwayLineBadge:
/** Line designation, e.g. '1', 'A', 'Q'. Case-insensitive. */
  line: string;
  /** 24 / 32 / 40px. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  className?: string;

dtsPropsFor.GlassmorphicTooltip:
/** Tooltip body. */
  content: React.ReactNode;
  /** Trigger element. */
  children: React.ReactNode;
  /** Hover delay in ms. Default 300. */
  delay?: number;
  /** Offset from the cursor. Default { x: 10, y: -10 }. */
  offset?: { x: number; y: number };
  className?: string;

dtsPropsFor.LegalLayout:
title: string;
  /** Rendered as the 'Last updated' line. */
  lastUpdated?: string;
  children: React.ReactNode;

dtsPropsFor.SubwayLinesBadges:
/** Line designations. Deduped and sorted (numbers before letters). */
  lines: string[];
  /** Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  /** 'default' renders round bullets; 'compact' renders small square pills. */
  variant?: 'default' | 'compact';
  showCount?: boolean;
  className?: string;

dtsPropsFor.SubwayBadge:
/** Caller supplies the colour classes — unlike SubwayLineBadge, which looks them up.
   * `name` is the SHORT DESIGNATION DRAWN INSIDE the badge (e.g. 'A', '7'), not the
   * route name — the only call site passes the line id. A long route name overflows
   * the badge. `color`/`textColor` are Tailwind class strings, e.g. 'bg-blue-600'. */
  line: { id: string; name: string; color: string; textColor: string };
  /** 32 / 48 / 64px — a larger scale than the other badges. Default 'md'. */
  size?: 'sm' | 'md' | 'lg';
  /** Wraps in a link to /line/<id> and adds hover scaling. Default true. */
  clickable?: boolean;

dtsPropsFor.ServiceAlert:
type: 'delay' | 'service_change' | 'good_service';
  message: string;
  /** Overrides the emoji chosen for the type. */
  icon?: string;

dtsPropsFor.CultureCard:
category: string;
  title: string;
  description: string;
  /** Emoji shown in the media area. Default '\ud83d\udcf7'. */
  image?: string;
  href?: string;

dtsPropsFor.AdSlot:
/** Placeholder dimensions. Default 'banner'. */
  size?: 'banner' | 'square' | 'leaderboard' | 'mobile_banner';
  className?: string;

dtsPropsFor.PostCard:
post: {
    title: string;
    slug: string;
    excerpt: string;
    category: string;
    tags: string[];
    featuredImage: string | null;
    featuredImageAlt: string | null;
    authorName: string;
    authorImage: string | null;
    publishedAt: string | null;
    readingTimeMinutes: number;
    views: number;
  };

dtsPropsFor.Pagination:
currentPage: number;
  totalPages: number;
  /** Link prefix, e.g. '/blog'. */
  basePath: string;

dtsPropsFor.AmenitiesCard:
amenities: {
    ada: boolean;
    elevators: boolean;
    restrooms: boolean;
    policePresence: boolean;
    wifi: boolean;
    yearBuilt: number;
  };
  className?: string;

dtsPropsFor.LiveArrivalsCard:
arrivals: {
    arrivals: Array<{
      line: string;
      direction: 'uptown' | 'downtown' | 'north' | 'south' | 'east' | 'west';
      destination: string;
      minutesAway: number;
      platform?: string;
    }>;
    lastUpdated: Date;
    dataSource: string;
  };
  className?: string;

dtsPropsFor.CrimeStatsCard:
crimeStats: {
    felonies: number;
    misdemeanors: number;
    violations: number;
    year: number;
    radius: number;
  };
  className?: string;

dtsPropsFor.StationDetailsCard:
station: { borough: string; lines: string[]; platforms: unknown[] };
  amenities: { stationType: 'underground' | 'elevated' | 'at-grade' };
  className?: string;
